  FT["SG-H986"] = {"id":"SG-H986","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S782-2015?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）（第 5 号）公告 2015","en":"Currency (Denominations and Characteristics of Coins) (No. 5) Notification 2015","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S782-2015","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H986-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins) (No. 5)\nNotification 2015\nPursuant to section 17(5) of the Currency Act, it is notified for general information that the denominations and characteristics of the coins to be issued on 1 January 2016 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H986-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF THE 2016 CHINESE ALMANAC COINS (YEAR OF THE MONKEY) TO BE ISSUED ON 1 JANUARY 2016\nDenomination\nMetal\nStandard Weight\nStandard Diameter\nStandard Thickness\nShape\nEdge\nDesign of Obverse\nDesign of Reverse\n200 Dollars\n999.9\nFine Gold\n155.52 g +\n0.20 g\n60.00 mm ±\n0.30 mm\n3.80 mm ±\n0.30 mm\nRound\nMilled and bearing the words “MONETARY AUTHORITY OF SINGAPORE” and a lion symbol.\nIn the centre is the Singapore Coat of Arms with the year-date “2016” below it, and the word “SINGAPORE” in the 4 official languages around the circumference of the coin. The position of the mintmark is at 5 o’clock for all the proof coins.\nInspired by Chinese calligraphy, the design features a monkey in the centre, with a peony incorporated in the body of the monkey. The appropriate ancient Chinese character of the “Heavenly Stems and Earthly Branches” representing the monkey, is repeated in the background of the design. The 2 ancient Chinese characters denoting the “Year of the Monkey” are at the lower centre of the design. The denomination of the coin in figures is above the design. The weight in troy oz/grams and fineness are at the upper circumference for all the coins, except for the $2 cupro-nickel proof‑like coin.\n100 Dollars\n999.9\nFine Gold\n31.103 g +\n0.05 g\n33.00 mm ±\n0.15 mm\n2.45 mm ±\n0.20 mm\nRound\n80 Dollars\n999\nFine Silver\n1000.00 g ±\n5.00 g\n100.00 mm ±\n2.00 mm\n13.00 mm ±\n2.00 mm\nRound\nMilled\n25 Dollars\n999\nFine Silver\n155.52 g ±\n0.90 g\n65.00 mm ±\n0.30 mm\n5.40 mm ±\n0.30 mm\nRound\nMilled and bearing the words “MONETARY AUTHORITY OF SINGAPORE” and a lion symbol.\n10 Dollars\n999\nFine Silver\n62.206 g ±\n0.20 g\n45.00 mm ±\n0.15 mm\n4.40 mm ±\n0.20 mm\nRound\n5 Dollars\n999.9\nFine Gold\n7.776 g +\n0.05 g\n21.96 mm ±\n0.125 mm\n1.55 mm ±\n0.20 mm\nRound\nMilled\n2 Dollars\n999\nFine Silver\n20.00 g ±\n0.20 g\n38.70 mm ±\n0.15 mm\n2.50 mm ±\n0.30 mm\nRound\nMilled and bearing the words “MONETARY AUTHORITY OF SINGAPORE” and a lion symbol.\n2 Dollars\n75% Copper\n25% Nickel\n20.00 g ±\n0.60 g\n38.70 mm ±\n0.15 mm\n2.50 mm ±\n0.30 mm\nRound\n1 Dollar\n999.9\nFine Gold\n0.30 g +\n0.04 g\n7.00 mm ±\n0.15 mm\n0.70 mm ±\n0.15 mm\nRound\nPlain\n(a)\n(b)\n(c)\n(d)\n(a)Reverse Design of the $200 Gold Proof Coin.\n(b)Reverse Design of the $100 Gold Proof Coin.\n(c)Reverse Design of the $5 Gold Proof Coin.\n(d)Reverse Design of the $1 Gold (Brilliant Uncirculated) Coin.\n(e)\n(e)Reverse Design of the $80 Silver Proof-like Coin.\n(f)\n(g)\n(h)\n(i)\n(f)Reverse Design of the $25 Silver Proof Coin.\n(g)Reverse Design of the $10 Silver Piedfort Proof Coin.\n(h)Reverse Design of the $2 Silver Proof Coin.\n(i)Reverse Design of the $2 Cupro-Nickel Proof-like Coin.\n(j)\n(k)\n(l)\n(m)\n(j)Common Obverse Design for $200 Gold Proof Coin, $100 Gold Proof Coin and $5 Gold Proof Coin.\n(k)Obverse Design for $1 Gold (Brilliant Uncirculated) Coin.\n(l)Common Obverse Design for $25 Silver Proof Coin, $10 Silver Piedfort Proof Coin and $2 Silver Proof Coin.\n(m)Common Obverse Design for $80 Silver Proof-like Coin and $2 Cupro-Nickel Proof-like Coin."}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) (No. 5) Notification 2015","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H987"] = {"id":"SG-H987","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S772-2013?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）（第 6 号）公告 2013","en":"Currency (Denominations and Characteristics of Coins) (No. 6) Notification 2013","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S772-2013","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H987-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins) (No. 6)\nNotification 2013\nPursuant to section 17(5) of the Currency Act, it is hereby notified for general information that the denominations and characteristics of the coins to be issued on 1st January 2014 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H987-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF COINS IN THE 2014 UNCIRCULATED COIN SET TO BE ISSUED ON 1ST JANUARY 2014\nDenomination\nMetal\nStandard Weight\nStandard\nDiameter\nStandard\nThickness\nShape\nEdge\nDesign of Obverse\nDesign of Reverse\n5 Cents\nMulti‑ply brass‑plated steel\n1.70 g ±\n0.07 g\n16.75 mm ±\n0.10 mm\n1.22 mm ±\n0.10 mm\nRound\nPlain\nThe Singapore Arms in the centre with the year-date “2014” below it and the word “SINGAPORE” in the 4 official languages around the circumference of the coins. A ring of dashes surrounds the Singapore Arms on both the 10‑cent and 50‑cent coins. The $1 coin has an octagonal frame along the circumference. The $5 coin has a ring of beads surrounding the Singapore Arms with a latent image below it depicting the year‑date “2014” and MAS logo.\nThe Esplanade — Theatres on the Bay in the centre with the figure “5” on the left and the word “CENTS” below it. There is a lion‑head outline on the top left of the coin.\n10 Cents\nMulti‑ply nickel‑plated steel\n2.36 g ±\n0.10 g\n18.50 mm ±\n0.10 mm\n1.38 mm ±\n0.10 mm\nRound\nInterrupted\nMilled\nThe Public Housing in the centre with the figure “10” on the left and the word “CENTS” below it. There is a lion‑head outline on the top left of the coin.\n20 Cents\nMulti‑ply nickel‑plated steel\n3.85 g ±\n0.15 g\n21.00 mm ±\n0.10 mm\n1.72 mm ±\n0.10 mm\nRound\nMilled\nThe Changi Airport in the centre with the figure “20” on the left and the word “CENTS” below it. There is a lion‑head outline on the top left of the coin.\n50 Cents\nMulti‑ply nickel‑plated steel\n6.56 g ±\n0.28 g\n23.00 mm ±\n0.10 mm\n2.45 mm ±\n0.10 mm\nRound\nMicro\nScalloped\nThe Port of Singapore in the centre with the figure “50” on the left and the word “CENTS” below it. There is a lion‑head outline on the top left of the coin. A ring of beads surrounds the design.\n1 Dollar\nBi‑metallic comprising inner circle of multi-ply nickel-plated steel and outer ring of multi‑ply brass‑plated steel\n7.62 g ±\n0.30 g\nInner circle:\n16 mm ± 0.10 mm\nOuter ring:\n24.65 mm ± 0.10 mm\n2.50 mm ±\n0.10 mm\nRound\nMilled\nThe Merlion in the centre with the figure “1” on the left and the word “DOLLAR” below it. The flower Vanda Miss Joaquim is in between the figure “1” and the Merlion. There is a lion-head outline on the top left of the coin. An octagonal frame surrounds the design.\n5 Dollars\nOuter Ring —\nCopper 75%\nNickel 25%\nCore —\nCopper 92%\nAluminium 6%\nNickel 2%\n6.70 g ±\n0.17 g\n23.30 mm ±\n0.125 mm\n2.30 mm ±\n0.152 mm\nScallop\nPlain\nThe flower, Vanda Miss Joaquim in the centre with the figure “$5” below it. A ring of beads surrounds the flower with the words “FIVE DOLLARS” and 5 dots at the outer ring of the coin.\n(a)\n(b)\n(c)\n(d)\n(e)\n(f)\n(a)Reverse Design of the 5-cent Third Series Uncirculated Coin.\n(b)Reverse Design of the 10-cent Third Series Uncirculated Coin.\n(c)Reverse Design of the 20-cent Third Series Uncirculated Coin.\n(d)Reverse Design of the 50-cent Third Series Uncirculated Coin.\n(e)Reverse Design of the $1 Third Series Uncirculated Coin.\n(f)Reverse Design of the $5 Uncirculated Coin.\n(a)\n(b)\n(c)\n(d)\n(e)\n(f)\n(g)\n(a)Obverse Design for the 5-cent Third Series Uncirculated Coin.\n(b)Obverse Design for the 10-cent Third Series Uncirculated Coin.\n(c)Obverse Design for the 20-cent Third Series Uncirculated Coin.\n(d)Obverse Design for the 50-cent Third Series Uncirculated Coin.\n(e)Obverse Design for the $1 Third Series Uncirculated Coin.\n(f)Obverse Design for the $5 Uncirculated Coin.\n(g)Latent Image."}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) (No. 6) Notification 2013","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H988"] = {"id":"SG-H988","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S179-2012?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2012","en":"Currency (Denominations and Characteristics of Coins) Notification 2012","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S179-2012","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H988-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2012\nPursuant to section 17(5) of the of the Currency Act, it is hereby notified for general information that the denominations and characteristics of the coins to be issued on 8th May 2012 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H988-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF THE 2012 NATIVE ORCHIDS OF SINGAPORE COINS TO BE ISSUED ON 8TH MAY 2012\nDenomination\nMetal\nStandard\nWeight\nStandard\nDiameter\nStandard\nThickness\nShape\nEdge\nDesign of Obverse\nDesign of Reverse\n5 Dollars\n999 Fine Silver\n31.10 g ± 0.20 g\n40.70 mm ± 0.20 mm\n3.05 mm ± 0.30 mm\nRound\nMilled\nThe Singapore Arms in the centre with the year-date \"2012\" below it and the word \"SINGAPORE\" in the 4 official languages around the circumference of the coin. The position of the mintmark is at 5 o'clock of the coin.\nThere are 2 different coin designs, each featuring one of the orchids named below:\n(a)Arundina graminifolia; and\n(b)Bulbophyllum macranthum.\nIn each design, the orchid is featured in colour at the centre with the name of the respective orchid along the upper circumference. The denomination is at the left of the coin, while the weight and fineness of the coin are at the lower left circumference.\n(a)Reverse Design of the $5 Silver Proof Coin (Arundina graminifolia).\n(b)Reverse Design of the $5 Silver Proof Coin (Bulbophyllum macranthum).\n(c)Common Obverse Design for the $5 Silver Proof Coins (Arundina graminifolia and Bulbophyllum macranthum)."}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2012","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H989"] = {"id":"SG-H989","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S221-2013?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2013","en":"Currency (Denominations and Characteristics of Coins) Notification 2013","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S221-2013","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H989-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2013\nPursuant to section 17(5) of the Currency Act, it is hereby notified for general information that the denominations and characteristics of the coins to be issued on 26th April 2013 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H989-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF COINS IN THE THIRD SERIES UNCIRCULATED COIN SET TO BE ISSUED ON 26TH APRIL 2013\nDenomination\nMetal\nStandard Weight\nStandard\nDimensions\nStandard\nThickness\nShape\nEdge\nDesign of Obverse\nDesign of Reverse\n5 Cents\nMulti-ply brass-plated steel\n1.70 g ±\n0.07 g\n16.75 mm ±\n0.10 mm\n1.22 mm ±\n0.10 mm\nRound\nPlain\nThe Singapore Arms in the centre with the year-date below it and the word “SINGAPORE” in the 4 official languages around the circumference of the coins. A ring of dashes surrounds the Singapore Arms on both the 10-cent and 50-cent coins. The $1 coin has an octagonal frame along the circumference.\nThe Esplanade – Theatres on the Bay in the centre with the figure “5” on the left and the word “CENTS” below it. There is a lion-head outline on the top left of the coin.\n10 Cents\nMulti-ply nickel-plated steel\n2.36 g ±\n0.10 g\n18.50 mm ±\n0.10 mm\n1.38 mm ±\n0.10 mm\nRound\nInterrupted Milled\nThe Public Housing in the centre with the figure “10” on the left and the word “CENTS” below it. There is a lion-head outline on the top left of the coin.\n20 Cents\nMulti-ply nickel-plated steel\n3.85 g ±\n0.15 g\n21.00 mm ±\n0.10 mm\n1.72 mm ±\n0.10 mm\nRound\nMilled\nThe Changi Airport in the centre with the figure “20” on the left and the word “CENTS” below it. There is a lion-head outline on the top left of the coin.\n50 Cents\nMulti-ply nickel-plated steel\n6.56 g ±\n0.28 g\n23.00 mm ±\n0.10 mm\n2.45 mm ±\n0.10 mm\nRound\nMicro Scalloped\nThe Singapore Arms in the centre with the year-date below it and the word “SINGAPORE” in the 4 official languages around the circumference of the coins. A ring of dashes surrounds the Singapore Arms on both the 10-cent and 50-cent coins. The $1 coin has an octagonal frame along the circumference.\nThe Port of Singapore in the centre with the figure “50” on the left and the word “CENTS” below it. There is a lion-head outline on the top left of the coin. A ring of beads surrounds the design.\n1 Dollar\nBi-metallic comprising inner circle of multi-ply nickel-plated steel and outer ring of multi-ply brass-plated steel\n7.62 g ±\n0.30 g\nInner circle:\n16 mm ±\n0.10 mm\nOuter ring:\n24.65 mm ±\n0.10 mm\n2.50 mm ±\n0.10 mm\nRound\nMilled\nThe Merlion in the centre with the figure “1” on the left and the word “DOLLAR” below it. The flower Vanda Miss Joaquim is in between the figure “1” and the Merlion. There is a lion-head outline on the top left of the coin. An octagonal frame surrounds the design.\n5 Cents\n99.9 Fine Silver with Gold Plating\n1.95 g ±\n0.25 g\n16.75 mm ±\n0.20 mm\n1.22 mm ±\n0.30 mm\nRound\nPlain\nThe Singapore Arms in the centre with the year – date below it and the word “SINGAPORE” in the 4 official languages around the circumference of the coins. A ring of dashes surrounds the Singapore Arms on both the 10-cent and 50-cent coins. The $1 coin has an octagonal frame along the circumference. The position of the mint mark is at 7 o’clock.\nThe Esplanade – Theatres on the Bay in the centre with the figure “5” on the left and the word “CENTS” below it. There is a lion-head outline on the top left of the coin.\n10 Cents\n99.9 Fine Silver\n2.98 g ±\n0.25 g\n18.50 mm ±\n0.20 mm\n1.38 mm ±\n0.30 mm\nRound\nInterrupted\nMilled\nThe Public Housing in the centre with the figure “10” on the left and the word “CENTS” below it. There is a lion-head outline on the top left of the coin.\n20 Cents\n99.9 Fine Silver\n4.94 g ±\n0.25 g\n21.00 mm ±\n0.20 mm\n1.72 mm ±\n0.30 mm\nRound\nMilled\nThe Changi Airport in the centre with the figure “20” on the left and the word “CENTS” below it. There is a lion-head outline on the top left of the coin.\n50 Cents\n99.9 Fine Silver\n9.54 g ±\n0.25 g\n23.00 mm ±\n0.20 mm\n2.60 mm ±\n0.30 mm\nRound\nMicro Scalloped\nThe Singapore Arms in the centre with the year – date below it and the word “SINGAPORE” in the 4 official languages around the circumference of the coins. A ring of dashes surrounds the Singapore Arms on both the 10-cent and 50-cent coins. The $1 coin has an octagonal frame along the circumference. The position of the mint mark is at 7 o’clock.\nThe Port of Singapore in the centre with the figure “50” on the left and the word “CENTS” below it. There is a lion-head outline on the top left of the coin. A ring of beads surrounds the design.\n1 Dollar\n99.9 Fine Silver with Gold Plating on the outer ring\n10.60 g ±\n0.25 g\nInner circle:\n16 mm ± 0.20 mm\nOuter ring:\n24.65 mm ±\n0.20 mm\n2.75 mm ±\n0.30 mm\nRound\nMilled\nThe Merlion in the centre with the figure “1” on the left and the word “DOLLAR” below it. The flower Vanda Miss Joaquim (in colour) is in between the figure “1” and the Merlion. There is a lion-head outline on the top left of the coin. An octagonal frame surrounds the design.\n(a)\n(b)\n(c)\n(d)\n(e)\n(a)Reverse Design of the 5-cent Third Series Uncirculated Coin.\n(b)Reverse Design of the 10-cent Third Series Uncirculated Coin.\n(c)Reverse Design of the 20-cent Third Series Uncirculated Coin.\n(d)Reverse Design of the 50-cent Third Series Uncirculated Coin.\n(e)Reverse Design of the $1 Third Series Uncirculated Coin.\n(f)\n(g)\n(h)\n(i)\n(j)\n(f)Obverse Design for the 5-cent Third Series Uncirculated Coin.\n(g)Obverse Design for the 10-cent Third Series Uncirculated Coin.\n(h)Obverse Design for the 20-cent Third Series Uncirculated Coin.\n(i)Obverse Design for the 50-cent Third Series Uncirculated Coin.\n(j)Obverse Design for the $1 Third Series Uncirculated Coin.\n(k)\n(l)\n(m)\n(n)\n(o)\n(k)Reverse Design of the 5-cent Third Series Silver Proof Coin.\n(l)Reverse Design of the 10-cent Third Series Silver Proof Coin.\n(m)Reverse Design of the 20-cent Third Series Silver Proof Coin.\n(n)Reverse Design of the 50-cent Third Series Silver Proof Coin.\n(o)Reverse Design of the $1 Third Series Silver Proof Coin.\n(p)\n(q)\n(r)\n(s)\n(t)\n(p)Obverse Design for the 5-cent Third Series Silver Proof Coin.\n(q)Obverse Design for the 10-cent Third Series Silver Proof Coin.\n(r)Obverse Design for the 20-cent Third Series Silver Proof Coin.\n(s)Obverse Design for the 50-cent Third Series Silver Proof Coin.\n(t)Obverse Design for the $1 Third Series Silver Proof Coin."}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2013","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H990"] = {"id":"SG-H990","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S475-2014?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2014","en":"Currency (Denominations and Characteristics of Coins) Notification 2014","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S475-2014","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H990-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency (Denominations and Characteristics of Coins)\nNotification 2014\nPursuant to section 17(5) of the Currency Act, it is hereby notified for general information that the denominations and characteristics of the coins to be issued on 23rd July 2014 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H990-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF THE 2014 NATIVE ORCHIDS OF SINGAPORE COINS TO BE ISSUED ON 23RD JULY 2014\nDenomination\nMetal\nStandard Weight\nStandard Diameter\nStandard Thickness\nShape\nEdge\nDesign of Obverse\nDesign of Reverse\n5 Dollars\n999\nFine Silver\n31.10 g ±\n0.20 g\n40.70 mm ±\n0.20 mm\n3.05 mm ±\n0.30 mm\nRound\nMilled\nThe Singapore Arms in the centre with the year‑date “2014” below it and the word “SINGAPORE” in the 4 official languages around the circumference of the coin. The position of the mintmark is at 5 o’clock of the coin.\nThere are 2 different coin designs, each featuring one of the orchids named below:\n(a) Phalaenopsis cornu-cervi; and\n(b) Coelogyne rochussenii.\nIn each design, the orchid is featured in colour at the centre with the name of the respective orchid along the upper circumference. The denomination is at the left of the coin, while the weight and fineness of the coin are at the lower left circumference.\n(a)\n(b)\n(c)\n(a)Reverse Design of the $5 Silver Proof Coin (Phalaenopsis cornu-cervi).\n(b)Reverse Design of the $5 Silver Proof Coin (Coelogyne rochussenii).\n(c)Common Obverse Design for the $5 Silver Proof Coins (Phalaenopsis cornu-cervi and Coelogyne rochussenii)."}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2014","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H991"] = {"id":"SG-H991","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S302-2015?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2015","en":"Currency (Denominations and Characteristics of Coins) Notification 2015","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S302-2015","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H991-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2015\nPursuant to section 17(5) of the Currency Act, it is notified for general information that the denominations and characteristics of the coins to be issued on 28 May 2015 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H991-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF THE SINGAPORE50 (SG50) COMMEMORATIVE COINS TO BE ISSUED ON 28 MAY 2015\nDenomination\nMetal\nStandard Weight\nStandard Diameter\nStandard Thickness\nShape\nEdge\nDesign of Obverse\nDesign of Reverse\n50 Dollars\n999.9\nFine Gold\n7.776 g +\n0.05 g\n21.96 mm\n± 0.15 mm\n1.55 mm ±\n0.20 mm\nRound\nMilled\nIn the centre is the Singapore Arms with the year-date “2015” below it, and the word “SINGAPORE” in the 4 official languages around the circumference of the coins. The position of the mintmark is at 5 o’clock of the $50 and $5 coins.\n$50 Gold Proof Coin\nThe design features our educators. The foreground depicts educators in a range of teaching activities. The background features a classroom scene in a primary school.\n$5 Silver Proof Coin\nThe design features higher education. The foreground depicts students, in colour, engaged in various fields of study — culinary arts at the Institute of Technical Education (ITE), engineering at a polytechnic, and medicine at a university. The background features the ITE Headquarters and ITE College Central, and National University of Singapore Bukit Timah campus.\n$2 Cupro-Nickel Proof-like Coin\nThe design features primary and secondary education. The foreground depicts students, in colour, engaged in diverse learning activities, in both academic and non-academic domains. The background features the Bukit Panjang Government High School.\nIn each design, the tagline ‘Education, Building Our Nation Together’ and the official SG50 logo (in colour only for the $5 silver proof coin and $2 cupro-nickel proof-like coin) are featured within a ribbon across the coin. The denomination of the coin in figures is below the SG50 logo at the right of the coin.\n5 Dollars\n999\nFine Silver\n31.103 g\n± 0.20 g\n40.70 mm\n± 0.20 mm\n3.20 mm ±\n0.30 mm\nRound\nMilled\n2 Dollars\n75% Copper\n25% Nickel\n20.00 g ±\n0.60 g\n38.70 mm\n± 0.15 mm\n2.50 mm ±\n0.30 mm\nRound\nMilled\n(a)\n(b)\n(c)\n(a)Reverse Design of the $50 Gold Proof Coin.\n(b)Reverse Design of the $5 Silver Proof Coin.\n(c)Reverse Design of the $2 Cupro-Nickel Proof-like Coin.\n(d)\n(e)\n(f)\n(d)Obverse Design for the $50 Gold Proof Coin.\n(e)Obverse Design for the $5 Silver Proof Coin.\n(f)Obverse Design for the $2 Cupro-Nickel Proof-like Coin."}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2015","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H992"] = {"id":"SG-H992","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S282-2016?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2016","en":"Currency (Denominations and Characteristics of Coins) Notification 2016","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S282-2016","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H992-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2016\nPursuant to section 17(5) of the Currency Act, it is notified for general information that the denominations and characteristics of the coins to be issued on 24 June 2016 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H992-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF THE SPLENDOUR OF NATIVE ORCHIDS SERIES COIN SET TO BE ISSUED ON 24 JUNE 2016\nDenomination\nMetal\nStandard Weight\nStandard Diameter\nStandard Thickness\nShape\nEdge\nDesign of Obverse\nDesign of Reverse\n1 Dollar\n999 Fine Silver\n8.56 g ± 0.30 g\n24.66 mm ± 0.25 mm\n2.06 mm ± 0.30 mm\nRound\nMilled\nIn each coin —\n(a)the background is shiny silver;\n(b)the Singapore Coat of Arms is engraved in the centre of the coin with the year-date “2016” below it;\n(c)the word “SINGAPORE” appears once in each of the 4 official languages and engraved on the coin near its circumference; and\n(d)the mintmark is engraved on the coin near its circumference at 5 o’clock of the coin.\n1. The coin set features 10 different coin designs, each featuring one of the orchids named below:\n(a)Cymbidium\nfinlaysonianum;\n(b)Grammatophyllum\nspeciosum;\n(c)Arundina\ngraminifolia;\n(d)Bulbophyllum\nmacranthum;\n(e)Bulbophyllum\nflabellum‑veneris;\n(f)Dendrobium\ncrumenatum;\n(g)Phalaenopsis\ncornu‑cervi;\n(h)Coelogyne\nrochussenii;\n(i)Dendrobium\nleonis;\n(j)Dendrobium\nsecundum.\n2. In each design —\n(a)the coin has a matt centre within a shiny silver annulus;\n(b)the denomination “$1” is in shiny silver and placed at 9 o’clock of the matt centre;\n(c)the orchid is featured in colour and occupies part of the matt centre complementary to the denomination and part of the right annulus;\n(d)the botanical name of the orchid is engraved and occupies the upper annulus beginning above 9 o’clock; and\n(e)the fineness of the coin is engraved and occupies the lower left quadrant of the annulus.\n(a)\n(b)\n(c)\n(d)\n(e)\n(f)\n(a)Reverse Design of the Cymbidium finlaysonianum coin of the Splendour of Native Orchids Series coin set.\n(b)Reverse Design of the Grammatophyllum speciosum coin of the Splendour of Native Orchids Series coin set.\n(c)Reverse Design of the Arundina graminifolia coin of the Splendour of Native Orchids Series coin set.\n(d)Reverse Design of the Bulbophyllum macranthum coin of the Splendour of Native Orchids Series coin set.\n(e)Reverse Design of the Bulbophyllum flabellum‑veneris coin of the Splendour of Native Orchids Series coin set.\n(f)Reverse Design of the Dendrobium crumenatum coin of the Splendour of Native Orchids Series coin set.\n(g)\n(h)\n(i)\n(j)\n(k)\n(g)Reverse Design of the Phalaenopsis cornu‑cervi coin of the Splendour of Native Orchids Series coin set.\n(h)Reverse Design of the Coelogyne rochussenii coin of the Splendour of Native Orchids Series coin set.\n(i)Reverse Design of the Dendrobium leonis coin of the Splendour of Native Orchids Series coin set.\n(j)Reverse Design of the Dendrobium secundum coin of the Splendour of Native Orchids Series coin set.\n(k)Common Obverse Design of each coin of the Splendour of Native Orchids Series coin set."}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2016","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H993"] = {"id":"SG-H993","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S758-2017?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2017","en":"Currency (Denominations and Characteristics of Coins) Notification 2017","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S758-2017","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H993-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2017\nPursuant to section 17(5) of the Currency Act, it is notified for general information that the denominations and characteristics of the coins to be issued on 5 January 2018 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H993-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF THE 2018 CHINESE ALMANAC COINS\n(YEAR OF THE DOG) TO BE ISSUED ON 5 JANUARY 2018\nPart 1\nDenomination\n$2\nMetal\n999 Fine Silver\nNickel-plated 99% Zinc\nStandard Weight\n7.776 g + 0.15 g\n20.000 g + 1.70 g\nStandard Diameter\n27.00 mm ± 0.30 mm\n40.70 mm ± 0.40 mm\nStandard Thickness\n1.90 mm ± 0.40 mm\n2.90 mm ± 0.40 mm\nShape\nRound\nEdge\nMilled\nDesign of Obverse\n1.The background of the $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin is shiny silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2018” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\nDesign of Reverse\n1.The background of the $2 silver proof-like colour coin and the $2 nickel‑plated zinc proof‑like coin is shiny silver.\n2.The $2 silver proof-like colour coin and the $2 nickel‑plated zinc proof‑like coin share a common design which features —\n(a)a dog engraved in the centre of the foreground;\n(b)orchids engraved in the left, centre and right of the middle ground, partially covered by the dog’s head, body and hind legs;\n(c)plants engraved in the right of the middle ground, partially covered by the dog’s head;\n(d)the Singapore Botanic Gardens Burkill Hall engraved in the left of the background, partially covered by the dog’s body and tail, and the orchids at the centre of the middle ground;\n(e)the Singapore Botanic Gardens Bandstand engraved in the right of the background, partially covered by feature (c); and\n(f)the respective denomination in figures engraved and placed at 12 o’clock, above the dog.\n3.The weight in troy oz and fineness of the coin are engraved above the denomination of the $2 silver proof‑like colour coin.\n4.The dog featured in the $2 silver proof‑like colour coin is in colour.\n$2 Silver Proof‑like Colour Coin\nReverse Design\nObverse Design\n$2 Nickel‑plated Zinc Proof‑like Coin\nReverse Design\nObverse Design\nPart 2\nDenomination\n$5\nMetal\n999 Fine Silver\n999.9 Fine Gold\nStandard Weight\n31.104 g + 0.40 g\n1.000 g + 0.05 g\nStandard Diameter/ Length and Width\n45.00 mm ± 0.40 mm\n1.Length: 15.00 mm ± 0.30 mm\n2.Width: 8.70 mm ± 0.30 mm\nStandard Thickness\n3.80 mm ± 0.70 mm\n3.30 mm ± 0.70 mm\n0.80 mm ± 0.30 mm\nShape\nOctagon\nFloral\nRectangle\nEdge\nPlain\nDesign of Obverse\n1.The background of the $5 silver proof coin and the $5 silver proof colour coin is shiny silver.\n2.The background of the $5 gold brilliant uncirculated coin is shiny gold.\n3.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2018” below it.\n4.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n5.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock for the $5 silver proof coin and the $5 silver proof colour coin.\nDesign of Reverse\n1.The background of the $5 silver proof coin and the $5 silver proof colour coin is shiny silver.\n2.The background of the $5 gold brilliant uncirculated coin is shiny gold.\n3.The $5 silver proof coin and the $5 silver proof colour coin share a common design which features —\n(a)a dog engraved in the centre of the foreground;\n(b)orchids engraved in the left, centre and right of the middle ground, partially covered by the dog’s head, body and hind legs;\n(c)plants engraved in the right of the middle ground, partially covered by the dog’s head;\n(d)the Singapore Botanic Gardens Burkill Hall engraved in the left of the background, partially covered by the dog’s body and tail, and the orchids at the centre of the middle ground;\n(e)the Singapore Botanic Gardens Bandstand engraved in the right of the background, partially covered by feature (c);\n(f)the respective denomination in figures engraved and placed at 12 o’clock, above the dog; and\n(g)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n4.The dog featured in the $5 silver proof colour coin is in colour.\n5.The $5 gold brilliant uncirculated coin features —\n(a)a dog engraved in the centre;\n(b)the denomination “$5” engraved and placed at 6 o’clock, below the dog; and\n(c)the weight in grams and fineness of the coin, engraved and placed at 12 o’clock, above the dog.\n$5 Silver Proof Coin\nReverse Design\nObverse Design\n$5 Silver Proof Colour Coin\nReverse Design\nObverse Design\n$5 Gold Brilliant Uncirculated Coin\nReverse Design\nObverse Design\nPart 3\nDenomination\n$20\nMetal\n999 Fine Silver\n999.9 Fine Gold\nStandard Weight\n155.518 g + 1.00 g\n7.776 g + 0.05 g\nStandard Diameter\n65.00 mm ± 0.80 mm\n21.96 mm ± 0.30 mm\nStandard Thickness\n9.50 mm ± 1.50 mm\n1.60 mm ± 0.40 mm\nShape\nRound\nEdge\nPlain\nMilled\nDesign of Obverse\n1.The background of the $20 silver proof coin is shiny silver.\n2.The background of the $20 gold proof coin is shiny gold.\n3.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2018” below it.\n4.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n5.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $20 silver proof coin is shiny silver.\n2.The background of the $20 gold proof coin is shiny gold.\n3.The $20 silver proof coin and the $20 gold proof coin share a common design which features —\n(a)a dog engraved in the centre of the foreground;\n(b)orchids engraved in the left, centre and right of the middle ground, partially covered by the dog’s head, body and hind legs;\n(c)plants engraved in the right of the middle ground, partially covered by the dog’s head;\n(d)the Singapore Botanic Gardens Burkill Hall engraved in the left of the background, partially covered by the dog’s body and tail, and the orchids at the centre of the middle ground;\n(e)the Singapore Botanic Gardens Bandstand engraved in the right of the background, partially covered by feature (c);\n(f)the respective denomination in figures engraved and placed at 12 o’clock, above the dog; and\n(g)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n$20 Silver Proof Coin\nReverse Design\nObverse Design\n$20 Gold Proof Coin\nReverse Design\nObverse Design\nPart 4\nDenomination\n$80\nMetal\n999 Fine Silver\nStandard Weight\n1000.000 g + 5.00 g\nLength and Width\n1.Length: 114.50 mm ± 2.00 mm\n2.Width: 60.50 mm ± 2.00 mm\nStandard Thickness\n19.00 mm ± 4.00 mm\nShape\nRectangle\nEdge\nPlain\nDesign of Obverse\n1.The background of the $80 silver proof‑like coin is matt silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2018” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\nDesign of Reverse\n1.The background of the $80 silver proof-like coin is shiny silver.\n2.The $80 silver proof-like coin features —\n(a)a dog engraved in the centre of the foreground with high relief;\n(b)orchids engraved in the left, centre and right of the middle ground, partially covered by the dog’s head, body and hind legs;\n(c)plants engraved in the left and right of the middle ground, partially covered by the dog’s head, hind legs and tail;\n(d)the Singapore Botanic Gardens Burkill Hall engraved in the area slightly to the left of the centre of the background, partially covered by the dog’s body and tail, and the orchids at the centre of the middle ground;\n(e)the Singapore Botanic Gardens Bandstand engraved in the top right corner of the background, partially covered by the plants in the right of the middle ground;\n(f)the denomination “$80”, engraved and placed at 3 o’clock, to the right of the dog overlapping the plants in the right of the middle ground; and\n(g)the weight in kilograms and fineness of the coin, engraved and placed at 12 o’clock, above the dog.\n$80 Silver Proof-like Coin\nReverse Design\nObverse Design\nPart 5\nDenomination\n$100\nMetal\n999.9 Fine Gold\nStandard Weight\n31.104 g + 0.10 g\nStandard Diameter\n40.00 mm ± 0.40 mm\nStandard Thickness\n2.50 mm ± 0.50 mm\nShape\nOctagon\nEdge\nPlain\nDesign of Obverse\n1.The background of the $100 gold proof coin is shiny gold.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2018” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $100 gold proof coin is shiny gold.\n2.The $100 gold proof coin features —\n(a)a dog engraved in the centre of the foreground;\n(b)orchids engraved in the left, centre and right of the middle ground, partially covered by the dog’s head, body and hind legs;\n(c)plants engraved in the right of the middle ground, partially covered by the dog’s head;\n(d)the Singapore Botanic Gardens Burkill Hall engraved in the left of the background, partially covered by the dog’s body and tail, and the orchids at the centre of the middle ground;\n(e)the Singapore Botanic Gardens Bandstand engraved in the right of the background, partially covered by feature (c);\n(f)the denomination “$100” engraved and placed at 12 o’clock, above the dog; and\n(g)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n$100 Gold Proof Coin\nReverse Design\nObverse Design\nPart 6\nDenomination\n$200\nMetal\n999.9 Fine Gold\nStandard Weight\n155.518 g + 0.20 g\nStandard Diameter\n60.00 mm ± 0.80 mm\nStandard Thickness\n5.50 mm ± 1.50 mm\nShape\nRound\nEdge\nPlain\nDesign of Obverse\n1.The background of the $200 gold proof coin is shiny gold.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2018” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $200 gold proof coin is shiny gold.\n2.The $200 gold proof coin features —\n(a)a dog engraved in the centre of the foreground;\n(b)orchids engraved in the left, centre and right of the middle ground, partially covered by the dog’s head, body and hind legs;\n(c)plants engraved in the right of the middle ground, partially covered by the dog’s head;\n(d)the Singapore Botanic Gardens Burkill Hall engraved in the left of the background, partially covered by the dog’s body and tail, and the orchids at the centre of the middle ground;\n(e)the Singapore Botanic Gardens Bandstand engraved in the right of the background, partially covered by feature (c);\n(f)the denomination “$200” engraved and placed at 12 o’clock, above the dog; and\n(g)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n$200 Gold Proof Coin\nReverse Design\nObverse Design"}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2017","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H994"] = {"id":"SG-H994","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S846-2018?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2018","en":"Currency (Denominations and Characteristics of Coins) Notification 2018","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S846-2018","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H994-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2018\nPursuant to section 17(5) of the Currency Act, it is notified for general information that the denominations and characteristics of the coins to be issued on 1 January 2019 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H994-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF THE 2019 CHINESE ALMANAC COINS\n(YEAR OF THE BOAR) TO BE ISSUED ON 1 JANUARY 2019\nPart 1\nDenomination\n$2\nMetal\n999 Fine Silver\nNickel‑plated 99% Zinc\nStandard Weight\n7.776 g + 0.15 g\n20.000 g + 1.70 g\nStandard Diameter\n27.00 mm ± 0.30 mm\n40.70 mm ± 0.40 mm\nStandard Thickness\n1.90 mm ± 0.40 mm\n2.90 mm ± 0.40 mm\nShape\nRound\nEdge\nMilled\nDesign of Obverse\n1.The background of the $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin is shiny silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2019” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\nDesign of Reverse\n1.The background of the $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin is shiny silver.\n2.The $2 silver proof-like colour coin and the $2 nickel‑plated zinc proof‑like coin share a common design which features —\n(a)a boar engraved in the centre of the foreground;\n(b)plants engraved in the left and right of the middle ground;\n(c)stones engraved in the foreground and left and right of the middle ground, with stones on the left of the middle ground partially covered by the boar’s right hind leg;\n(d)a kelong engraved in the right of the background, with the stilts of the kelong partially covered by the boar’s head;\n(e)the entrance structure of Pulau Ubin and a bumboat on water engraved in the left of the background, with the railings of the entrance structure partially covered by feature (a); and\n(f)the respective denomination in figures engraved and placed at 12 o’clock, above the boar.\n3.The weight in troy oz and fineness of the coin are engraved above the denomination of the $2 silver proof‑like colour coin.\n4.The boar featured in the $2 silver proof‑like colour coin is in colour.\n$2 Silver Proof‑like Colour Coin\nReverse Design\nObverse Design\n$2 Nickel‑plated Zinc Proof‑like Coin\nReverse Design\nObverse Design\nPart 2\nDenomination\n$5\nMetal\n999 Fine Silver\n999.9 Fine Gold\nStandard Weight\n31.104 g + 0.40 g\n1.000 g + 0.05 g\nStandard Diameter/\nLength and Width\n45.00 mm ± 0.40 mm\n1.Length: 15.00 mm ± 0.30 mm\n2.Width: 8.70 mm ± 0.30 mm\nStandard Thickness\n3.80 mm ± 0.70 mm\n3.30 mm ± 0.70 mm\n0.80 mm ± 0.30 mm\nShape\nOctagon\nFloral\nRectangle\nEdge\nPlain\nDesign of Obverse\n1.The background of the $5 silver proof coin and the $5 silver proof colour coin is shiny silver.\n2.The background of the $5 gold brilliant uncirculated coin is shiny gold.\n3.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2019” below it.\n4.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n5.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock for the $5 silver proof coin and the $5 silver proof colour coin.\nDesign of Reverse\n1.The background of the $5 silver proof coin and the $5 silver proof colour coin is shiny silver.\n2.The background of the $5 gold brilliant uncirculated coin is shiny gold.\n3.The $5 silver proof coin and the $5 silver proof colour coin share a common design which features —\n(a)a boar engraved in the centre of the foreground;\n(b)plants engraved in the left and right of the middle ground;\n(c)stones engraved in the foreground and left and right of the middle ground, with stones on the left of the middle ground partially covered by the boar’s right hind leg;\n(d)a kelong engraved in the right of the background, with the stilts of the kelong partially covered by the boar’s head;\n(e)the entrance structure of Pulau Ubin and a bumboat on water engraved in the left of the background, with the railings of the entrance structure partially covered by feature (a);\n(f)the respective denomination in figures engraved and placed at 12 o’clock, above the boar; and\n(g)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n4.The boar featured in the $5 silver proof colour coin is in colour.\n5.The $5 gold brilliant uncirculated coin features —\n(a)a boar engraved in the centre;\n(b)the denomination “$5” engraved and placed at 6 o’clock, below the boar; and\n(c)the weight in grams and fineness of the coin, engraved and placed at 12 o’clock, above the boar.\n$5 Silver Proof Coin\nReverse Design\nObverse Design\n$5 Silver Proof Colour Coin\nReverse Design\nObverse Design\n$5 Gold Brilliant Uncirculated Coin\nReverse Design\nObverse Design\nPart 3\nDenomination\n$20\nMetal\n999 Fine Silver\n999.9 Fine Gold\nStandard Weight\n155.518 g + 1.00 g\n7.776 g + 0.05 g\nStandard Diameter\n65.00 mm ± 0.80 mm\n21.96 mm ± 0.30 mm\nStandard Thickness\n9.50 mm ± 1.50 mm\n1.60 mm ± 0.40 mm\nShape\nRound\nEdge\nPlain\nMilled\nDesign of Obverse\n1.The background of the $20 silver proof coin is shiny silver.\n2.The background of the $20 gold proof coin is shiny gold.\n3.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2019” below it.\n4.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n5.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $20 silver proof coin is shiny silver.\n2.The background of the $20 gold proof coin is shiny gold.\n3.The $20 silver proof coin and the $20 gold proof coin share a common design which features —\n(a)a boar engraved in the centre of the foreground;\n(b)plants engraved in the left and right of the middle ground;\n(c)stones engraved in the foreground and left and right of the middle ground, with stones on the left of the middle ground partially covered by the boar’s right hind leg;\n(d)a kelong engraved in the right of the background, with the stilts of the kelong partially covered by the boar’s head;\n(e)the entrance structure of Pulau Ubin and a bumboat on water engraved in the left of the background, with the railings of the entrance structure partially covered by feature (a);\n(f)the respective denomination in figures engraved and placed at 12 o’clock, above the boar; and\n(g)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n$20 Silver Proof Coin\nReverse Design\nObverse Design\n$20 Gold Proof Coin\nReverse Design\nObverse Design\nPart 4\nDenomination\n$80\nMetal\n999 Fine Silver\nStandard Weight\n1000.000 g + 5.00 g\nLength and Width\n1.Length: 114.50 mm ± 2.00 mm\n2.Width: 60.50 mm ± 2.00 mm\nStandard Thickness\n19.00 mm ± 4.00 mm\nShape\nRectangle\nEdge\nPlain\nDesign of Obverse\n1.The background of the $80 silver proof‑like coin is matt silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2019” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\nDesign of Reverse\n1.The background of the $80 silver proof‑like coin is shiny silver.\n2.The $80 silver proof‑like coin features —\n(a)a boar engraved in the centre of the foreground;\n(b)plants engraved in the left and right of the middle ground;\n(c)stones engraved in the left and right of the foreground;\n(d)a kelong, with a water feature leading to it, engraved in the right of the background;\n(e)the entrance structure of Pulau Ubin and a bumboat on water engraved in the left of the background, with the railings of the entrance structure partially covered by feature (a);\n(f)the denomination “$80” engraved and placed at 3 o’clock, to the right of the boar overlapping the plants and water feature in the right of the middle ground; and\n(g)the weight in kilograms and fineness of the coin, engraved and placed at 12 o’clock, above the boar.\n$80 Silver Proof‑like Coin\nReverse Design\nObverse Design\nPart 5\nDenomination\n$100\nMetal\n999.9 Fine Gold\nStandard Weight\n31.104 g + 0.10 g\nStandard Diameter\n40.00 mm ± 0.40 mm\nStandard Thickness\n2.50 mm ± 0.50 mm\nShape\nOctagon\nEdge\nPlain\nDesign of Obverse\n1.The background of the $100 gold proof coin is shiny gold.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2019” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $100 gold proof coin is shiny gold.\n2.The $100 gold proof coin features —\n(a)a boar engraved in the centre of the foreground;\n(b)plants engraved in the left and right of the middle ground;\n(c)stones engraved in the foreground and left and right of the middle ground, with stones on the left of the middle ground partially covered by the boar’s right hind leg;\n(d)a kelong engraved in the right of the background, with the stilts of the kelong partially covered by the boar’s head;\n(e)the entrance structure of Pulau Ubin and a bumboat on water engraved in the left of the background, with the railings of the entrance structure partially covered by feature (a);\n(f)the denomination “$100” engraved and placed at 12 o’clock, above the boar; and\n(g)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n$100 Gold Proof Coin\nReverse Design\nObverse Design\nPart 6\nDenomination\n$200\nMetal\n999.9 Fine Gold\nStandard Weight\n155.518 g + 0.20 g\nStandard Diameter\n60.00 mm ± 0.80 mm\nStandard Thickness\n5.50 mm ± 1.50 mm\nShape\nRound\nEdge\nPlain\nDesign of Obverse\n1.The background of the $200 gold proof coin is shiny gold.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2019” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $200 gold proof coin is shiny gold.\n2.The $200 gold proof coin features —\n(a)a boar engraved in the centre of the foreground;\n(b)plants engraved in the left and right of the middle ground;\n(c)stones engraved in the foreground and left and right of the middle ground, with stones on the left of the middle ground partially covered by the boar’s right hind leg;\n(d)a kelong engraved in the right of the background, with the stilts of the kelong partially covered by the boar’s head;\n(e)the entrance structure of Pulau Ubin and a bumboat on water engraved in the left of the background, with the railings of the entrance structure partially covered by feature (a);\n(f)the denomination “$200” engraved and placed at 12 o’clock, above the boar; and\n(g)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n$200 Gold Proof Coin\nReverse Design\nObverse Design"}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2018","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H995"] = {"id":"SG-H995","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S838-2019?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2019","en":"Currency (Denominations and Characteristics of Coins) Notification 2019","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S838-2019","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H995-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2019\nPursuant to section 17(5) of the Currency Act, it is notified for general information that the denominations and characteristics of the coins to be issued on 1 January 2020 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H995-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF THE 2020 CHINESE ALMANAC COINS\n(YEAR OF THE RAT) TO BE ISSUED ON 1 JANUARY 2020\nPart 1\nDenomination\n$2\nMetal\n999 Fine Silver\nNickel‑plated 99% Zinc\nStandard Weight\n7.776 g + 0.15 g\n20.000 g + 1.70 g\nStandard Diameter\n27.00 mm ± 0.30 mm\n40.70 mm ± 0.40 mm\nStandard Thickness\n1.90 mm ± 0.40 mm\n2.90 mm ± 0.40 mm\nShape\nRound\nEdge\nMilled\nDesign of Obverse\n1.The background of the $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin is shiny silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2020” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\nDesign of Reverse\n1.The background of the $2 silver proof-like colour coin and the $2 nickel‑plated zinc proof‑like coin is shiny silver.\n2.The $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin share a common design which features —\n(a)a rat standing on a wooden log, engraved in the centre of the foreground, with its tail and body partially covering an observatory pod and the trees that are engraved in the left and middle respectively of the middle ground;\n(b)a shelter along a boardwalk engraved in the right of the middle ground, with the boardwalk and its stilts partially covered by the rat’s ears and head;\n(c)trees in the middle ground and background, on the left and right of the shelter respectively;\n(d)a water feature in the right of the middle ground between the boardwalk and the rat; and\n(e)the denomination “$2” engraved and placed at 12 o’clock, above the trees on the left of the shelter.\n3.The weight in troy oz and fineness of the coin are engraved above the denomination of the $2 silver proof‑like colour coin.\n4.The rat featured in the $2 silver proof‑like colour coin is in colour.\n$2 Silver Proof‑like Colour Coin\nReverse Design\nObverse Design\n$2 Nickel‑plated Zinc Proof‑like Coin\nReverse Design\nObverse Design\nPart 2\nDenomination\n$5\nMetal\n999 Fine Silver\n999.9 Fine Gold\nStandard Weight\n31.104 g + 0.40 g\n1.000 g + 0.05 g\nStandard Diameter/ Length and Width\n45.00 mm ± 0.40 mm\n1.Length: 15.00 mm ± 0.30 mm\n2.Width: 8.70 mm ± 0.30 mm\nStandard Thickness\n3.80 mm ± 0.70 mm\n3.30 mm ± 0.70 mm\n0.80 mm ± 0.30 mm\nShape\nOctagon\nFloral\nRectangle\nEdge\nPlain\nDesign of Obverse\n1.The background of the $5 silver proof coin and the $5 silver proof colour coin is shiny silver.\n2.The background of the $5 gold brilliant uncirculated coin is shiny gold.\n3.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2020” below it.\n4.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n5.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock for the $5 silver proof coin and the $5 silver proof colour coin.\nDesign of Reverse\n1.The background of the $5 silver proof coin and the $5 silver proof colour coin is shiny silver.\n2.The background of the $5 gold brilliant uncirculated coin is shiny gold.\n3.The $5 silver proof coin and the $5 silver proof colour coin share a common design which features —\n(a)a rat standing on a wooden log, engraved in the centre of the foreground, with its tail and body partially covering an observatory pod and the trees that are engraved in the left and middle respectively of the middle ground;\n(b)a shelter along a boardwalk engraved in the right of the middle ground, with the boardwalk and its stilts partially covered by the rat’s ears and head;\n(c)trees in the middle ground and background, on the left and right of the shelter respectively;\n(d)a water feature in the right of the middle ground between the boardwalk and the rat;\n(e)the denomination “$5” engraved and placed at 12 o’clock, above the trees on the left of the shelter; and\n(f)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n4.The rat featured in the $5 silver proof colour coin is in colour.\n5.The $5 gold brilliant uncirculated coin features —\n(a)a rat engraved in the centre;\n(b)the denomination “$5” engraved and placed at 6 o’clock, below the rat; and\n(c)the weight in grams and fineness of the coin, engraved and placed at 12 o’clock, above the rat.\n$5 Silver Proof Coin\nReverse Design\nObverse Design\n$5 Silver Proof Colour Coin\nReverse Design\nObverse Design\n$5 Gold Brilliant Uncirculated Coin\nReverse Design\nObverse Design\nPart 3\nDenomination\n$20\nMetal\n999 Fine Silver\n999.9 Fine Gold\nStandard Weight\n155.518 g + 1.00 g\n7.776 g + 0.05 g\nStandard Diameter\n65.00 mm ± 0.80 mm\n21.96 mm ± 0.30 mm\nStandard Thickness\n9.50 mm ± 1.50 mm\n1.60 mm ± 0.40 mm\nShape\nRound\nEdge\nPlain\nMilled\nDesign of Obverse\n1.The background of the $20 silver proof coin is shiny silver.\n2.The background of the $20 gold proof coin is shiny gold.\n3.The Singapore Coat of Arms is engraved in the centre of the coin with the year-date “2020” below it.\n4.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n5.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $20 silver proof coin is shiny silver.\n2.The background of the $20 gold proof coin is shiny gold.\n3.The $20 silver proof coin and the $20 gold proof coin share a common design which features —\n(a)a rat standing on a wooden log, engraved in the centre of the foreground, with its tail and body partially covering an observatory pod and the trees that are engraved in the left and middle respectively of the middle ground;\n(b)a shelter along a boardwalk engraved in the right of the middle ground, with the boardwalk and its stilts partially covered by the rat’s ears and head;\n(c)trees in the middle ground and background, on the left and right of the shelter respectively;\n(d)a water feature in the right of the middle ground between the boardwalk and the rat;\n(e)the denomination “$20” engraved and placed at 12 o’clock, above the trees on the left of the shelter; and\n(f)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n$20 Silver Proof Coin\nReverse Design\nObverse Design\n$20 Gold Proof Coin\nReverse Design\nObverse Design\nPart 4\nDenomination\n$80\nMetal\n999 Fine Silver\nStandard Weight\n1000.000 g + 5.00 g\nLength and Width\n1.Length: 114.50 mm ± 2.00 mm\n2.Width: 60.50 mm ± 2.00 mm\nStandard Thickness\n19.00 mm ± 4.00 mm\nShape\nRectangle\nEdge\nPlain\nDesign of Obverse\n1.The background of the $80 silver proof-like coin is matt silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2020” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\nDesign of Reverse\n1.The background of the $80 silver proof-like coin is shiny silver.\n2.The $80 silver proof-like coin features —\n(a)a rat standing on a wooden log, engraved in the centre of the foreground, with its tail and body partially covering an observatory pod, bushes, trees and the boardwalk that are engraved in the left of the middle ground;\n(b)a shelter along a boardwalk engraved in the right of the middle ground, with the boardwalk and its stilts partially covered by the rat’s ears, head, tail and body;\n(c)bushes and trees in the middle ground on the left of the shelter and trees in the background on the right of the shelter;\n(d)water features in the right of the middle ground between the boardwalk and the rat and in the left of the foreground next to the wooden log;\n(e)the denomination “$80” engraved and placed at 3 o’clock, to the right of the rat overlapping the water feature and the stilts of the boardwalk in the right of the middle ground; and\n(f)the weight in kilograms and fineness of the coin, engraved and placed at 12 o’clock, above the trees on the left of the shelter.\n$80 Silver Proof‑like Coin\nReverse Design\nObverse Design\nPart 5\nDenomination\n$100\nMetal\n999.9 Fine Gold\nStandard Weight\n31.104 g + 0.10 g\nStandard Diameter\n40.00 mm ± 0.40 mm\nStandard Thickness\n2.50 mm ± 0.50 mm\nShape\nOctagon\nEdge\nPlain\nDesign of Obverse\n1.The background of the $100 gold proof coin is shiny gold.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2020” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $100 gold proof coin is shiny gold.\n2.The $100 gold proof coin features —\n(a)a rat standing on a wooden log, engraved in the centre of the foreground, with its tail and body partially covering an observatory pod and the trees that are engraved in the left and middle respectively of the middle ground;\n(b)a shelter along a boardwalk engraved in the right of the middle ground, with the boardwalk and its stilts partially covered by the rat’s ears and head;\n(c)trees in the middle ground and background, on the left and right of the shelter respectively;\n(d)a water feature in the right of the middle ground between the boardwalk and the rat;\n(e)the denomination “$100” engraved and placed at 12 o’clock, above the trees on the left of the shelter; and\n(f)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n$100 Gold Proof Coin\nReverse Design\nObverse Design\nPart 6\nDenomination\n$200\nMetal\n999.9 Fine Gold\nStandard Weight\n155.518 g + 0.20 g\nStandard Diameter\n60.00 mm ± 0.80 mm\nStandard Thickness\n5.50 mm ± 1.50 mm\nShape\nRound\nEdge\nPlain\nDesign of Obverse\n1.The background of the $200 gold proof coin is shiny gold.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year-date “2020” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $200 gold proof coin is shiny gold.\n2.The $200 gold proof coin features —\n(a)a rat standing on a wooden log, engraved in the centre of the foreground, with its tail and body partially covering an observatory pod and the trees that are engraved in the left and middle respectively of the middle ground;\n(b)a shelter along a boardwalk engraved in the right of the middle ground, with the boardwalk and its stilts partially covered by the rat’s ears and head;\n(c)trees in the middle ground and background, on the left and right of the shelter respectively;\n(d)a water feature in the right of the middle ground between the boardwalk and the rat;\n(e)the denomination “$200” engraved and placed at 12 o’clock, above the trees on the left of the shelter; and\n(f)the weight in troy oz and fineness of the coin, engraved above the denomination of the coin.\n$200 Gold Proof Coin\nReverse Design\nObverse Design"}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2019","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H996"] = {"id":"SG-H996","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S1056-2020?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2020","en":"Currency (Denominations and Characteristics of Coins) Notification 2020","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S1056-2020","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H996-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2020\nPursuant to section 17(5) of the Currency Act, it is notified for general information that the denominations and characteristics of the coins to be issued on 1 January 2021 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H996-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDescription of the 2021 Chinese Almanac Coins\n(Year of the Ox) to be issued on 1 January 2021\nPART 1\nDenomination\n$2\nMetal\n999 Fine Silver\nNickel‑plated 99% Zinc\nStandard Weight\n7.776 g + 0.15 g\n20.000 g + 1.70 g\nStandard Diameter\n27.00 mm ± 0.30 mm\n40.70 mm ± 0.40 mm\nStandard Thickness\n1.90 mm ± 0.40 mm\n2.90 mm ± 0.40 mm\nShape\nRound\nEdge\nMilled\nDesign of Obverse\n1.The background of the $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin is shiny silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2021” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\nDesign of Reverse\n1.The background of the $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin is shiny silver.\n2.The $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin share a common design which features —\n(a)an ox standing in the centre of the foreground, with its head, left horn, body and tail partially covering a bird hide and with its right foreleg slightly lifted;\n(b)a bird hide engraved in the background with shrubs and creepers on both the left and right sides of the bird hide; and\n(c)the denomination “$2” engraved and placed at 6 o’clock, below the ox.\n3.The weight in troy oz and fineness of the coin are engraved above the ox of the $2 silver proof‑like colour coin.\n4.The ox featured in the $2 silver proof‑like colour coin is in colour.\n$2 Silver Proof‑like Colour Coin\nReverse Design\nObverse Design\n$2 Nickel‑plated Zinc Proof‑like Coin\nReverse Design\nObverse Design\nPART 2\nDenomination\n$5\nMetal\n999 Fine Silver\n999.9 Fine Gold\nStandard Weight\n31.104 g + 0.40 g\n1.000 g + 0.05 g\nStandard Diameter/ Length and Width\n45.00 mm ± 0.40 mm\n1.Length: 15.00 mm ± 0.30 mm\n2.Width: 8.70 mm ± 0.30 mm\nStandard Thickness\n3.80 mm ± 0.70 mm\n3.30 mm ± 0.70 mm\n0.80 mm ± 0.30 mm\nShape\nOctagon\nFloral\nRectangle\nEdge\nPlain\nDesign of Obverse\n1.The background of the $5 silver proof coin and the $5 silver proof colour coin is shiny silver.\n2.The background of the $5 gold brilliant uncirculated coin is shiny gold.\n3.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2021” below it.\n4.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n5.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock for the $5 silver proof coin and the $5 silver proof colour coin.\nDesign of Reverse\n1.The background of the $5 silver proof coin and the $5 silver proof colour coin is shiny silver.\n2.The background of the $5 gold brilliant uncirculated coin is shiny gold.\n3.The $5 silver proof coin and the $5 silver proof colour coin share a common design which features —\n(a)an ox standing in the centre of the foreground, with its head, left horn, body and tail partially covering a bird hide and with its right foreleg slightly lifted;\n(b)a bird hide engraved in the background with shrubs and creepers on both the left and right sides of the bird hide;\n(c)the denomination “$5” engraved and placed at\n6 o’clock, below the ox; and\n(d)the weight in troy oz and fineness of the coin, engraved above the ox.\n4.The ox featured in the $5 silver proof colour coin is in colour.\n5.The $5 gold brilliant uncirculated coin features —\n(a)an ox engraved in the centre;\n(b)the denomination “$5” engraved and placed at 6 o’clock, below the ox; and\n(c)the weight in grams and fineness of the coin, engraved and placed at 12 o’clock, above the ox.\n$5 Silver Proof Coin\nReverse Design\nObverse Design\n$5 Silver Proof Colour Coin\nReverse Design\nObverse Design\n$5 Gold Brilliant Uncirculated Coin\nReverse Design\nObverse Design\nPART 3\nDenomination\n$20\nMetal\n999 Fine Silver\n999.9 Fine Gold\nStandard Weight\n155.518 g + 1.00 g\n7.776 g + 0.05 g\nStandard Diameter\n65.00 mm ± 0.80 mm\n21.96 mm ± 0.30 mm\nStandard Thickness\n9.50 mm ± 1.50 mm\n1.60 mm ± 0.40 mm\nShape\nRound\nEdge\nPlain\nMilled\nDesign of Obverse\n1.The background of the $20 silver proof coin is shiny silver.\n2.The background of the $20 gold proof coin is shiny gold.\n3.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2021” below it.\n4.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n5.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $20 silver proof coin is shiny silver.\n2.The background of the $20 gold proof coin is shiny gold.\n3.The $20 silver proof coin and the $20 gold proof coin share a common design which features —\n(a)an ox standing in the centre of the foreground, with its head, left horn, body and tail partially covering a bird hide and with its right foreleg slightly lifted;\n(b)a bird hide engraved in the background with shrubs and creepers on both the left and right sides of the bird hide;\n(c)the denomination “$20” engraved and placed at 6 o’clock, below the ox; and\n(d)the weight in troy oz and fineness of the coin, engraved above the ox.\n$20 Silver Proof Coin\nReverse Design\nObverse Design\n$20 Gold Proof Coin\nReverse Design\nObverse Design\nPART 4\nDenomination\n$80\nMetal\n999 Fine Silver\nStandard Weight\n1000.000 g + 5.00 g\nLength and Width\n1.Length: 114.50 mm ± 2.00 mm\n2.Width: 60.50 mm ± 2.00 mm\nStandard Thickness\n19.00 mm ± 4.00 mm\nShape\nRectangle\nEdge\nPlain\nDesign of Obverse\n1.The background of the $80 silver proof‑like coin is matt silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2021” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\nDesign of Reverse\n1.The background of the $80 silver proof‑like coin is shiny silver.\n2.The $80 silver proof‑like coin features —\n(a)an ox standing in the centre of the foreground, with its head, horns, body and tail partially covering a bird hide and with its right foreleg slightly lifted;\n(b)a bird hide engraved in the background with shrubs, plants and creepers on both the left and right sides of the bird hide;\n(c)the denomination “$80” engraved and placed at 3 o’clock, to the right of the ox, partially covering the right side of the bird hide and the shrubs, plants and creepers on that side of the bird hide; and\n(d)the weight in kilograms and fineness of the coin, engraved and placed at 12 o’clock, above the middle of the bird hide.\n$80 Silver Proof‑like Coin\nReverse Design\nObverse Design\nPART 5\nDenomination\n$100\nMetal\n999.9 Fine Gold\nStandard Weight\n31.104 g + 0.10 g\nStandard Diameter\n40.00 mm ± 0.40 mm\nStandard Thickness\n2.50 mm ± 0.50 mm\nShape\nOctagon\nEdge\nPlain\nDesign of Obverse\n1.The background of the $100 gold proof coin is shiny gold.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2021” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $100 gold proof coin is shiny gold.\n2.The $100 gold proof coin features —\n(a)an ox standing in the centre of the foreground, with its head, left horn, body and tail partially covering a bird hide and with its right foreleg slightly lifted;\n(b)a bird hide engraved in the background with shrubs and creepers on both the left and right sides of the bird hide;\n(c)the denomination “$100” engraved and placed at 6 o’clock, below the ox; and\n(d)the weight in troy oz and fineness of the coin, engraved above the ox.\n$100 Gold Proof Coin\nReverse Design\nObverse Design\nPART 6\nDenomination\n$200\nMetal\n999.9 Fine Gold\nStandard Weight\n155.518 g + 0.20 g\nStandard Diameter\n60.00 mm ± 0.80 mm\nStandard Thickness\n5.50 mm ± 1.50 mm\nShape\nRound\nEdge\nPlain\nDesign of Obverse\n1.The background of the $200 gold proof coin is shiny gold.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2021” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $200 gold proof coin is shiny gold.\n2.The $200 gold proof coin features —\n(a)an ox standing in the centre of the foreground, with its head, left horn, body and tail partially covering a bird hide and with its right foreleg slightly lifted;\n(b)a bird hide engraved in the background with shrubs and creepers on both the left and right sides of the bird hide;\n(c)the denomination “$200” engraved and placed at 6 o’clock, below the ox; and\n(d)the weight in troy oz and fineness of the coin, engraved above the ox.\n$200 Gold Proof Coin\nReverse Design\nObverse Design"}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2020","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H997"] = {"id":"SG-H997","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S857-2021?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2021","en":"Currency (Denominations and Characteristics of Coins) Notification 2021","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S857-2021","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H997-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act\n(CHAPTER 69)\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2021\nPursuant to section 17(5) of the Currency Act, it is notified for general information that the denominations and characteristics of the coins to be issued on 12 November 2021 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H997-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDESCRIPTION OF THE HAWKER CULTURE IN SINGAPORE\nUNESCO COMMEMORATIVE COINS TO BE ISSUED\nON 12 November 2021\nDenomination\n$2\n$5\nMetal\nNickel-plated 99% Zinc\n999 Fine Silver\nStandard Weight\n20.000 g + 1.70 g\n31.104 g + 0.40 g\nStandard Diameter\n40.70 mm ± 0.40 mm\n40.70 mm ± 0.40 mm\nStandard Thickness\n2.90 mm ± 0.40 mm\n3.05 mm ± 0.40 mm\nShape\nRound\nRound\nEdge\nMilled\nMilled\nDesign of Obverse\n1.The background of the $2 nickel‑plated zinc proof‑like coin and the $5 silver proof colour coin is shiny silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2021” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock for the $5 silver proof colour coin.\nDesign of Reverse\n1.The background of the $2 nickel‑plated zinc proof‑like coin and the $5 silver proof colour coin is shiny silver.\n2.The words “HAWKER CULTURE IN SINGAPORE” are engraved on the upper circumference with the words “UNESCO INTANGIBLE CULTURAL HERITAGE OF HUMANITY” engraved on the lower circumference of the coin.\n3.The $2 nickel-plated zinc proof‑like coin and the $5 silver proof colour coin share a common design which features —\n(a)in the foreground — 3 male hawkers and one female hawker from diverse cultural backgrounds preparing the following local favourites (in clockwise direction from the top‑left hawker):\n(i)Hokkien Mee (fried prawn noodles);\n(ii)Nasi Lemak (fragrant rice cooked in coconut milk, served with fried chicken, egg, anchovies, peanuts, cucumber and sambal);\n(iii)Kaya Toast accompanied with soft‑boiled eggs and Kopi (coffee); and\n(iv)Roti Prata (Indian flatbread served with curry) and Indian Rojak; and\n(b)in the background and all in engraving —\n(i)patrons, young and old, enjoying their meals in a hawker centre setting, are depicted in the left and centre;\n(ii)a chicken rice stall is depicted on the right; and\n(iii)a tray return rack is depicted to the left of the chicken rice stall.\n4.The $2 nickel-plated zinc proof‑like coin also features —\n(a)its foreground minted in relief engraving; and\n(b)the denomination “$2” engraved and placed at 6 o’clock, between the male and female hawkers.\n5.The $5 silver proof colour coin also features —\n(a)its foreground in colour; and\n(b)the denomination “$5” engraved and placed at 6 o’clock, between the male and female hawkers.\n$2 Nickel-plated Zinc Proof-like Coin\nReverse Design\nObverse Design\n$5 Silver Proof Colour Coin\nReverse Design\nObverse Design"}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2021","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H998"] = {"id":"SG-H998","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S992-2022?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2022","en":"Currency (Denominations and Characteristics of Coins) Notification 2022","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S992-2022","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H998-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act 1967\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2022\nPursuant to section 17(5) of the Currency Act 1967, it is notified for general information that the denominations and characteristics of the coins to be issued on 1 January 2023 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H998-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDescription of the 2023 Chinese Almanac Coins\n(Year of the Rabbit) to be issued on 1 January 2023\nPart 1\nDenomination\n$2\nMetal\n999 Fine Silver\nNickel-plated 99% Zinc\nStandard Weight\n7.776 g + 0.15 g\n20.000 g + 1.70 g\nStandard Diameter\n27.00 mm ± 0.30 mm\n40.70 mm ± 0.40 mm\nStandard Thickness\n1.90 mm ± 0.40 mm\n2.90 mm ± 0.40 mm\nShape\nRound\nEdge\nMilled\nDesign of Obverse\n1.The background of the $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin is shiny silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2023” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\nDesign of Reverse\n1.The background of the $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin is shiny silver.\n2.The $2 silver proof‑like colour coin and the $2 nickel‑plated zinc proof‑like coin share a common design which features —\n(a)a rabbit in the centre of the foreground leaping forward, with its left ear and head partially covering the Amber Beacon Tower, both forelegs on the grass, with its body and both hindlegs partially covering the sea and the Bedok Jetty;\n(b)the Bedok Jetty in the background on the left side of the coin;\n(c)the Amber Beacon Tower with a breakwater rock structure behind the Amber Beacon Tower in the background on the right side of the coin;\n(d)plants in the foreground on the left side of the coin below the 2 hindlegs of the rabbit; and\n(e)the denomination “$2” engraved and placed at 12 o’clock, above the rabbit.\n3.The weight in troy oz and fineness of the coin are engraved above the rabbit of the $2 silver proof‑like colour coin.\n4.The rabbit featured in the $2 silver proof‑like colour coin is in colour.\n$2 Silver Proof-like Colour Coin\nReverse Design\nObverse Design\n$2 Nickel-plated Zinc Proof-like Coin\nReverse Design\nObverse Design\nPart 2\nDenomination\n$5\nMetal\n999 Fine Silver\n999.9 Fine Gold\nStandard Weight\n31.104 g + 0.40 g\n1.000 g + 0.05 g\nStandard Diameter/\nLength and Width\n45.00 mm ± 0.40 mm\n1.Length: 15.00 mm ± 0.30 mm\n2.Width: 8.70 mm ± 0.30 mm\nStandard Thickness\n3.80 mm ± 0.70 mm\n3.30 mm ± 0.70 mm\n0.80 mm ± 0.30 mm\nShape\nOctagon\nFloral\nRectangle\nEdge\nPlain\nDesign of Obverse\n1.The background of the $5 silver proof coin and the $5 silver proof colour coin is shiny silver.\n2.The background of the $5 gold brilliant uncirculated coin is shiny gold.\n3.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2023” below it.\n4.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n5.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock for the $5 silver proof coin and the $5 silver proof colour coin.\nDesign of Reverse\n1.The background of the $5 silver proof coin and the $5 silver proof colour coin is shiny silver.\n2.The background of the $5 gold brilliant uncirculated coin is shiny gold.\n3.The $5 silver proof coin and the $5 silver proof colour coin share a common design which features —\n(a)a rabbit in the centre of the foreground leaping forward, with its left ear and head partially covering the Amber Beacon Tower, both forelegs on the grass, with its body and both hindlegs partially covering the sea and the Bedok Jetty;\n(b)the Bedok Jetty in the background on the left side of the coin;\n(c)the Amber Beacon Tower with a breakwater rock structure behind the Amber Beacon Tower in the background on the right side of the coin;\n(d)plants in the foreground on the left side of the coin below the 2 hindlegs of the rabbit; and\n(e)the denomination “$5” engraved and placed at 12 o’clock, above the rabbit.\n4.The rabbit featured in the $5 silver proof colour coin is in colour.\n5.The $5 gold brilliant uncirculated coin features —\n(a)a rabbit engraved in the centre;\n(b)the denomination “$5” engraved and placed at 6 o’clock, below the rabbit; and\n(c)the weight in grams and fineness of the coin, engraved and placed at 12 o’clock, above the rabbit.\n$5 Silver Proof Coin\nReverse Design\nObverse Design\n$5 Silver Proof Colour Coin\nReverse Design\nObverse Design\n$5 Gold Brilliant Uncirculated Coin\nReverse Design\nObverse Design\nPart 3\nDenomination\n$20\nMetal\n999 Fine Silver\n999.9 Fine Gold\nStandard Weight\n155.518 g + 1.00 g\n7.776 g + 0.05 g\nStandard Diameter\n65.00 mm ± 0.80 mm\n21.96 mm ± 0.30 mm\nStandard Thickness\n9.50 mm ± 1.50 mm\n1.60 mm ± 0.40 mm\nShape\nRound\nEdge\nPlain\nMilled\nDesign of Obverse\n1.The background of the $20 silver proof coin is shiny silver.\n2.The background of the $20 gold proof coin is shiny gold.\n3.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2023” below it.\n4.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n5.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $20 silver proof coin is shiny silver.\n2.The background of the $20 gold proof coin is shiny gold.\n3.The $20 silver proof coin and the $20 gold proof coin share a common design which features —\n(a)a rabbit in the centre of the foreground leaping forward, with its left ear and head partially covering the Amber Beacon Tower, both forelegs on the grass, with its body and both hindlegs partially covering the sea and the Bedok Jetty;\n(b)the Bedok Jetty in the background on the left side of the coin;\n(c)the Amber Beacon Tower with a breakwater rock structure behind the Amber Beacon Tower in the background on the right side of the coin;\n(d)plants in the foreground on the left side of the coin below the 2 hindlegs of the rabbit;\n(e)the denomination “$20” engraved and placed at 12 o’clock, above the rabbit; and\n(f)the weight in troy oz and fineness of the coin, engraved above the rabbit.\n$20 Silver Proof Coin\nReverse Design\nObverse Design\n$20 Gold Proof Coin\nReverse Design\nObverse Design\nPart 4\nDenomination\n$80\nMetal\n999 Fine Silver\nStandard Weight\n1000.000 g + 5.00 g\nLength and Width\n1.Length: 114.50 mm ± 2.00 mm\n2.Width: 60.50 mm ± 2.00 mm\nStandard Thickness\n19.00 mm ± 4.00 mm\nShape\nRectangle\nEdge\nPlain\nDesign of Obverse\n1.The background of the $80 silver proof‑like coin is matt silver.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2023” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\nDesign of Reverse\n1.The background of the $80 silver proof‑like coin is shiny silver.\n2.The $80 silver proof-like coin features —\n(a)a rabbit in the centre of the foreground leaping forward, with its left ear partially covering the Amber Beacon Tower, both forelegs on the grass, with its body and both hindlegs partially covering the Bedok Jetty and breakwater rock structure;\n(b)the Bedok Jetty by the sea in the background, and a breakwater rock structure and a palm tree in the middle ground on the left side of the coin;\n(c)the Amber Beacon Tower with a breakwater rock structure behind the Amber Beacon Tower in the background on the right side of the coin;\n(d)plants in the foreground on both the left and right sides of the coin;\n(e)the denomination “$80” engraved and placed at 9 o’clock, to the left of the rabbit, partially covering a palm tree and the Bedok Jetty; and\n(f)the weight in kilograms and fineness of the coin, engraved and placed at 12 o’clock, above the rabbit.\n$80 Silver Proof-like Coin\nReverse Design\nObverse Design\nPart 5\nDenomination\n$100\nMetal\n999.9 Fine Gold\nStandard Weight\n31.104 g + 0.10 g\nStandard Diameter\n40.00 mm ± 0.40 mm\nStandard Thickness\n2.50 mm ± 0.50 mm\nShape\nOctagon\nEdge\nPlain\nDesign of Obverse\n1.The background of the $100 gold proof coin is shiny gold.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2023” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $100 gold proof coin is shiny gold.\n2.The $100 gold proof coin features —\n(a)a rabbit in the centre of the foreground leaping forward, with its left ear and head partially covering the Amber Beacon Tower, both forelegs on the grass, with its body and both hindlegs partially covering the sea and the Bedok Jetty;\n(b)the Bedok Jetty in the background on the left side of the coin;\n(c)the Amber Beacon Tower with a breakwater rock structure behind the Amber Beacon Tower in the background on the right side of the coin;\n(d)plants in the foreground on the left side of the coin below the 2 hindlegs of the rabbit;\n(e)the denomination “$100” engraved and placed at 12 o’clock, above the rabbit; and\n(f)the weight in troy oz and fineness of the coin, engraved above the rabbit.\n$100 Gold Proof Coin\nReverse Design\nObverse Design\nPart 6\nDenomination\n$200\nMetal\n999.9 Fine Gold\nStandard Weight\n155.518 g + 0.20 g\nStandard Diameter\n60.00 mm ± 0.80 mm\nStandard Thickness\n5.50 mm ± 1.50 mm\nShape\nRound\nEdge\nPlain\nDesign of Obverse\n1.The background of the $200 gold proof coin is shiny gold.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with the year‑date “2023” below it.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The mintmark is engraved on the coin around the Singapore Coat of Arms at 5 o’clock.\nDesign of Reverse\n1.The background of the $200 gold proof coin is shiny gold.\n2.The $200 gold proof coin features —\n(a)a rabbit in the centre of the foreground leaping forward, with its left ear and head partially covering the Amber Beacon Tower, both forelegs on the grass, with its body and both hindlegs partially covering the sea and the Bedok Jetty;\n(b)the Bedok Jetty in the background on the left side of the coin;\n(c)the Amber Beacon Tower with a breakwater rock structure behind the Amber Beacon Tower in the background on the right side of the coin;\n(d)plants in the foreground on the left side of the coin below the 2 hindlegs of the rabbit;\n(e)the denomination “$200” engraved and placed at 12 o’clock, above the rabbit; and\n(f)the weight in troy oz and fineness of the coin, engraved above the rabbit.\n$200 Gold Proof Coin\nReverse Design\nObverse Design"}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2022","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["SG-H999"] = {"id":"SG-H999","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/CA1967-S561-2023?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"WHOLE","title":{"zh":"货币（硬币面额与特征）公告 2023","en":"Currency (Denominations and Characteristics of Coins) Notification 2023","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation CA1967-S561-2023","completenessNote":"该法规为单篇法律文书，无分节结构；正文按官方 front 抬头逐字全录，共 2 条。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H999-A1","no":1,"noLabel":{"en":"1"},"text":{"en":"Currency Act 1967\nCurrency\n(Denominations and Characteristics of Coins)\nNotification 2023\nPursuant to section 17(5) of the Currency Act 1967, it is notified for general information that the denomination and characteristics of the coin to be issued on 14 August 2023 by the Monetary Authority of Singapore are as shown in the Schedule."}},{"id":"SG-H999-A900000","no":900000,"noLabel":{"en":"THE SCHEDULE"},"text":{"en":"THE SCHEDULE\nDescription of the 100th birth anniversary of\nMr Lee Kuan Yew commemorative coin to be issued\non 14 August 2023\nDenomination\n$10\nMetal\nAluminium Bronze\nStandard Weight\n13.90 g ± 0.42 g\nStandard Diameter\n30.00 mm ± 0.40 mm\nStandard Thickness\n2.90 mm ± 0.40 mm\nShape\nRound\nEdge\nMilled\nDesign of Obverse\n1.The coin is gold in colour.\n2.The Singapore Coat of Arms is engraved in the centre of the coin with a dual latent image directly below it and above the word “SINGAPORE”. The dual latent image features Mr Lee Kuan Yew’s birth year “1923” and his 100th birth anniversary “2023”.\n3.The word “SINGAPORE” appears once in each of the 4 official languages and is engraved on the coin around the Singapore Coat of Arms.\n4.The words “100TH BIRTH ANNIVERSARY” and “LEE KUAN YEW” are engraved along the top and bottom circumferences of the coin, respectively, with Mr Lee Kuan Yew’s life period “1923” and “2015” on the left and right of his name, respectively.\nDesign of Reverse\n1.The coin is gold in colour.\n2.The coin features —\n(a)in the foreground —\n(i)a portrait of Mr Lee Kuan Yew on the right side of the coin; and\n(ii)the Marina Barrage on the bottom left side of the coin, with the right part partially covered by the portrait of Mr Lee Kuan Yew; and\n(b)in the background —\n(i)the skyline of the Raffles Place financial district on the top, with the right part partially covered by the portrait of Mr Lee Kuan Yew; and\n(ii)the Fullerton Hotel and National Gallery Singapore on the left side and right side of the coin, respectively, in front of the Raffles Place financial district skyline. The right side of the National Gallery Singapore is partially covered by the portrait of Mr Lee Kuan Yew.\n3.The denomination “$10” is engraved and placed at 9 o’clock of the coin, between the Marina Barrage and Raffles Place financial district skyline.\n$10 Aluminium Bronze Coin\nReverse Design\nObverse Design"}}],"pack":"sg-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Currency (Denominations and Characteristics of Coins) Notification 2023","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
